// Offline-First: Frontend SPA renders QR via qrcode.react; n8n packages trace_url and delegates SHA-256 hash chaining to Postgres trigger.
const input = $input.first().json;
const body = input.body || input;
const row = body?.event?.data?.new || body;

const id = row.id || 'c0000000-0000-0000-0000-000000000001';
const tenant_id = row.tenant_id || 'a0000000-0000-0000-0000-000000000000';
const batch_code = row.batch_code || 'LOT-DEMO-001';
const product_name = row.product_name || 'Nông sản NodusCore';
const public_trace_key = row.public_trace_key || batch_code;
const existingMeta = (row.metadata && typeof row.metadata === 'object') ? row.metadata : {};

const trace_url = `http://localhost:3000/trace/${public_trace_key}`;

const merged_metadata = {
  ...existingMeta,
  trace_url,
  qr_generated_at: new Date().toISOString()
};

const audit_snapshot = {
  batch_id: id,
  batch_code,
  product_name,
  public_trace_key,
  trace_url,
  action: 'QR_GENERATED'
};

return [{
  json: {
    id,
    tenant_id,
    batch_code,
    product_name,
    public_trace_key,
    trace_url,
    merged_metadata,
    audit_snapshot
  }
}];
